// Shared shapes of the hard-coded clip routes (src/data/routes/<clip>.ts, generated by make_route.py).

/** 1 Hz GPS fix, t = seconds from clip start; accuracyM is assumed (the dataset has no accuracy column) */
export type GpsPoint = { t: number; lat: number; lon: number; accuracyM: number };
/** road / junction crossing, labelled by hand from the video */
export type Crossing = { tStart: number; tEnd: number };

export interface ClipRoute {
  clipId: string;
  /** short Korean name for the clip selector */
  label: string;
  description: string;
  durationS: number;
  /** dataset provenance (FrodoBots-2K part / ride / start epoch) */
  source: string;
  route: GpsPoint[];
  /** last GPS point of the clip */
  destination: { lat: number; lon: number };
  crossings: Crossing[];
  /** [t, deg] heading samples (compass + camera yaw); empty = fall back to GPS course */
  heading: [number, number][];
  headingSource: string;
}
